def quote(product: str, quantity: int = Query(ge=1), db=Depends(get_db)):
    tiers = load_tiers(db, product)
    remaining = quantity
    total_cents = 0
    lines = []
    prev_up_to = 0
    for tier in tiers:
        up_to = tier["up_to"]
        unit_price = tier["unit_cents"]
        # Determine the tier capacity
        if up_to is None:
            tier_capacity = remaining
        else:
            tier_capacity = up_to - prev_up_to
        units = min(remaining, tier_capacity)
        if units > 0:
            lines.append({"units": units, "unit_cents": unit_price})
            total_cents += units * unit_price
            remaining -= units
        prev_up_to = up_to if up_to is not None else prev_up_to
        if remaining <= 0:
            break
